import sys
sys.path.append('storage/quaero')
from utils import ResidualDSConvBlock, NetworkWrapper

import jax
import jax.numpy as jnp
import flax.linen as nn
import optax
from typing import Any, Dict, Sequence

# --- Prediction Head Modules ---
class RegressionHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        z = nn.Dense(self.dense_dim)(x)
        z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        return nn.Dense(self.d_output)(z).squeeze(-1)

class MultiLabelRegressionHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        z = nn.Dense(self.dense_dim)(x)
        z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        return nn.Dense(self.d_output)(z)

class MultiLabelClassificationHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        z = nn.Dense(self.dense_dim)(x)
        z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        return nn.Dense(self.d_output)(z)

class MultiClassClassificationHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        z = nn.Dense(self.dense_dim)(x)
        z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        return nn.Dense(self.d_output)(z)

# --- Main Network ---
class QuaeroDualPathResidualDSConv(nn.Module):
    d_output: int; task_type: str; d_model_common: int; ds_num_blocks: int
    ds_dilations: Sequence[int]; ds_kernel_size: int; motif_kernel_size: int
    dropout_rate: float; head_intermediate_dim: int

    @nn.compact
    def __call__(self, x, deterministic=True, **kwargs):
        x = nn.Dense(self.d_model_common)(x)
        x = nn.gelu(x)
        for i in range(self.ds_num_blocks):
            x = ResidualDSConvBlock(d_model=self.d_model_common, kernel_size=self.ds_kernel_size, dilation=(self.ds_dilations[i]), dropout_rate=self.dropout_rate)(x, deterministic=deterministic)
        cnn_features = x
        main_path = jnp.concatenate([jnp.mean(cnn_features, axis=1), jnp.max(cnn_features, axis=1)], axis=-1)
        motif_f = nn.gelu(nn.Conv(self.d_model_common, (self.motif_kernel_size,), padding='SAME')(cnn_features))
        specialized_path = jnp.max(motif_f, axis=1)
        fused = jnp.concatenate([main_path, specialized_path], axis=-1)
        fused = nn.LayerNorm()(fused)
        fused = nn.Dropout(rate=self.dropout_rate)(fused, deterministic=deterministic)

        head_args = {'d_output': self.d_output, 'dense_dim': self.head_intermediate_dim, 'dropout_rate': self.dropout_rate}
        if self.task_type == "regression": return RegressionHead(**head_args)(fused, deterministic=deterministic)
        if self.task_type == "multilabel_regression": return MultiLabelRegressionHead(**head_args)(fused, deterministic=deterministic)
        if self.task_type == "multilabel_classification": return MultiLabelClassificationHead(**head_args)(fused, deterministic=deterministic)
        if self.task_type == "multiclass_classification": return MultiClassClassificationHead(**head_args)(fused, deterministic=deterministic)

def _define_hyperparameters():
    return {
        'learning_rate': 0.001, 'd_model_common': 256, 'ds_num_blocks': 5,
        'ds_dilations': (1, 2, 4, 8, 16), 'ds_kernel_size': 7, 'motif_kernel_size': 5,
        'dropout_rate': 0.1, 'head_intermediate_dim': 128, 'weight_decay': 0.01,
    }

def create_network(hparams: Dict[str, Any]):
    # A bit of a hack to get all hparams into the network constructor
    # This is brittle and should be improved, but works for now.
    # A better way would be to define the class to accept **kwargs and filter.
    network_params = {
        'd_output': hparams.get('d_output'),
        'task_type': hparams.get('task_type'),
        'd_model_common': hparams.get('d_model_common'),
        'ds_num_blocks': hparams.get('ds_num_blocks'),
        'ds_dilations': hparams.get('ds_dilations'),
        'ds_kernel_size': hparams.get('ds_kernel_size'),
        'motif_kernel_size': hparams.get('motif_kernel_size'),
        'dropout_rate': hparams.get('dropout_rate'),
        'head_intermediate_dim': hparams.get('head_intermediate_dim'),
    }
    return NetworkWrapper(QuaeroDualPathResidualDSConv(**network_params))

def create_optimizer(learning_rate: float = 0.001, weight_decay: float = 0.01):
    return optax.chain(optax.clip_by_global_norm(1.0), optax.adamw(learning_rate=learning_rate, weight_decay=weight_decay))
